#include <bits/stdc++.h>
using namespace std;
using ll = int64_t;

int main() {
	cin.tie(0)->sync_with_stdio(0);
	int l,b; cin>>l>>b;
	string s; cin>>s;
	vector<array<int,3>> button(b);
	vector<array<bool,3>> vis(l+b,{false,false,false});
	vector<vector<int>> adj(l+b);
	for (int i=0;i<b;i++) {
		button[i].fill(-1);
		int k; cin>>k;
		while (k--) {
			int light; cin>>light, light--;
			adj[b+light].push_back(i);
			adj[i].push_back(b+light);
		}
	}

	auto dfs = [&](auto dfs, int x, int t) -> int {
		if (vis[x][t]) return 0;
		vis[x][t]=true;
		if (x>=b) {
			int d=3-string_view("RGB").find(s[x-b]);
			for (int y: adj[x]) if (button[y][t]!=-1) d+=3-button[y][t];
			bool found=false;
			for (int y: adj[x]) if (button[y][t]==-1) {
				assert(!found);
				button[y][t]=d%3, found=true;
			}
			if (!found && d%3!=0) return INT_MAX;
		}
		int o=x<b ? button[x][t] : 0;
		for (int y: adj[x]) {
			int v=dfs(dfs,y,t);
			if (v==INT_MAX) return v;
			o+=v;
		}
		return o;
	};

	int o=0;
	for (int i=0; i<l+b; i++) {
		int d=INT_MAX;
		for (int j=0;j<3;j++) {
			if (i<b) button[i][j]=j;
			d=min(d,dfs(dfs,i,j));
		}
		if (d==INT_MAX) {
			cout<<"impossible\n";
			return 0;
		}
		o+=d;
	}

	cout<<o<<"\n";
}

